      "number": "Kapitola 2",
      "titleCs": "Část II — Práh Nové Země",
      "titleEn": "Část II — Práh Nové Země",
      "epigraphCs": "",
      "epigraphEn": "",
      "color": "#32CD32",
      "rgb": "50,205,50",
      "sectionsCs": [
        {
          "body": "Terra Nova nezačíná utopií."
        },
        {
          "body": "Začíná přesným poznáním, že starý svět se nehroutí proto, že by mu chybělo dost dat, kapitálu nebo výpočetního výkonu. Hroutí se proto, že se jeho základní logika odpojila od života."
        },
        {
          "body": "Práh je v této knize okamžik, kdy už nejde jen obdivovat horizont. Je to bod, kde se musí rozhodnout, co ze starého světa ještě může být přeneseno a co už musí zůstat za námi."
        },
        {
          "body": "**1. Civilizace, která všechno umí a nic neuzdravuje**"
        },
        {
          "body": "Naše doba umí téměř všechno kromě jedné věci: vytvořit celek, v němž by technický růst současně znamenal větší míru důstojnosti, pravdivosti a propojenosti."
        },
        {
          "body": "Umíme zrychlovat."
        },
        {
          "body": "Neumíme tím samým pohybem zrát."
        },
        {
          "body": "Umíme propojit miliardy zařízení."
        },
        {
          "body": "Neumíme tím samým pohybem vytvořit miliardy vztahů, které by nebyly degradovány na transakci, kliknutí nebo metrickou jednotku zisku."
        },
        {
          "body": "Umíme modelovat počasí, geny i jazyk."
        },
        {
          "body": "Ale stále neumíme zaručit, že technologie, která roste exponenciálně, nebude sloužit starému vědomí strachu ještě efektivněji než dřív."
        },
        {
          "body": "Práh Nové Země tedy nezačíná technologií. Začíná odmítnutím falešného předpokladu, že více stejného principu jednou vyprodukuje jiný výsledek."
        },
        {
          "body": "**2. Co musí skončit**"
        },
        {
          "body": "Některé věci se nedají reformovat donekonečna. Musí se vyčerpat."
        },
        {
          "body": "Musí skončit logika, podle které:"
        },
        {
          "body": "- příroda je jen zásobárna surovin,\n- komunita je jen přechodná sociální vrstva mezi jednotlivcem a státem,\n- zdraví je trh,\n- vzdělávání je produkce pracovních jednotek,\n- umělá inteligence je nástroj pro maximalizaci závislosti a kontroly,\n- ekonomika je mechanika extrakce, nikoli forma péče,\n- spiritualita je soukromý doplněk světa, jehož infrastruktura zůstává beze změny."
        },
        {
          "body": "Terra Nova nevzniká jako reakce proti jedné instituci. Vzniká jako pokus opustit celý rámec, v němž se život pořád znovu podřizuje akumulaci, strachu a oddělenosti."
        },
        {
          "body": "**3. Co musí začít**"
        },
        {
          "body": "Nová Země nezačíná jednou velkou revolucí. Začíná novou skladbou vztahů."
        },
        {
          "body": "Musí začít svět, v němž:"
        },
        {
          "body": "- energie není zbraní proti závislým,\n- jídlo není jen komoditou, ale základní vrstvou svobody,\n- komunita není nouzový sentiment, ale provozní forma civilizace,\n- technologie je vybírána podle toho, zda slouží životu,\n- peníze nejsou směr, ale médium směru,\n- péče není vedlejší sektor, ale střed architektury,\n- hvězdy nejsou útěkem od Země, ale důsledkem toho, že jsme se na Zemi konečně naučili žít méně destruktivně."
        },
        {
          "body": "**4. Pět vrstev pravdy**"
        },
        {
          "body": "Jedním z hlavních úkolů této ORG verze je neplést dohromady nesouměřitelné druhy tvrzení."
        },
        {
          "body": "Proto Terra Nova v této podobě pracuje s pěti vrstvami:"
        },
        {
          "body": "1. **Mýtus a symbol**\n   Ne proto, aby nahrazoval fakta, ale aby dával smysl směru."
        },
        {
          "body": "2. **Filosofická interpretace**\n   Ne proto, aby vytvářela novou ideologii, ale aby pojmenovala hlubší souvislosti."
        },
        {
          "body": "3. **Živá realita**\n   To, co je ověřitelné teď: runtime, dokumentace, provoz, architektura."
        },
        {
          "body": "4. **Stavební plán**\n   To, co už má tvar a záměr, ale ještě není plně rozvinuté."
        },
        {
          "body": "5. **Horizont**\n   To, co musí zůstat poctivě přiznanou vizí."
        },
        {
          "body": "Jakmile tyto vrstvy ztratíme z dohledu, kniha se rozpadne. Buď do technokratické příručky bez duše, nebo do exaltovaného textu, který přestane být důvěryhodný."
        },
        {
          "body": "**5. Odpověď TerraNova**"
        },
        {
          "body": "Terra Nova není odpovědí jedné disciplíny."
        },
        {
          "body": "Není to čistě politický program.\nNení to čistě blockchain whitepaper.\nNení to čistě duchovní kniha.\nNení to čistě design obce budoucnosti."
        },
        {
          "body": "Je to pokus znovu složit to, co se v modernitě rozpadlo na separované resorty."
        },
        {
          "body": "Proto v této knize patří vedle sebe:"
        },
        {
          "body": "- půda a protokol,\n- komunita a konsensus,\n- péče a compute,\n- orbitální horizont a obyčejný chléb,\n- vnitřní proměna a provozní disciplína."
        },
        {
          "body": "Nová Země nezačne tehdy, když si o ní poprvé přečteme."
        },
        {
          "body": "Začne tehdy, když se tato nová skladba vztahů stane obyvatelnou."
        },
        {
          "body": "Od této chvíle už se tedy neptáme jen proč."
        },
        {
          "body": "Začneme se ptát **jak**."
        },
        {
          "body": "Právě proto další část nemíří nejdřív do abstraktní politiky ani do velkého plánu institucí. Míří ke komunitě, krajině a nejmenší obyvatelné buňce Nové Země. Pokud totiž změna nedokáže sestoupit až tam, zůstane práh jen krásnou formulací."
        },
        {
          "body": "*[← 01-MOST-CTYRI-KNIHY.md](./01-MOST-CTYRI-KNIHY.md)* | *[→ 03-KOMUNITY-A-KRAJINA.md](./03-KOMUNITY-A-KRAJINA.md)*"
        }
      ],
