          "body": "**Klíčová architektonická volba — Fáze 2:** Vyžaduje 2 MB RAM jako pracovní prostor. ASIC čipy — specializovaný hardware — mají malou paměť. Velký paměťový požadavek = ASIC nemá výhodu. Těžit může kdokoliv s normálním počítačem nebo GPU. **Demokratická těžba jako záměrné architektonické rozhodnutí.**"
