      "epigraphCs": "*\"Nehledejte pravidla venku, na mramoru nebo v parlamentech. Napsali jsme je do rovnic a uložili do každého jednoho atomu, který tuto síť živí.\"*",
      "epigraphEn": "*\"Nehledejte pravidla venku, na mramoru nebo v parlamentech. Napsali jsme je do rovnic a uložili do každého jednoho atomu, který tuto síť živí.\"*",
