        {
          "body": "**Uchováno v Krystalovém Jádrě Issobelly 1, Přístupové Úrovně Všem Obyvatelům**"
        },
        {
          "body": "Pokud čteš tento záznam, a nezáleží na tom jestli jsi na Zemi v roce 2030 nebo na palubě kolonizační lodi na okraji Oortova oblaku v roce 2150, neseš s sebou zodpovědnost strážce. Jsi jedním z Guardianů sítě. Kód ZION není jen software nebo kryptoměna."
        },
        {
          "body": "ZION je architekturou přežití a symbiózy. Pamatuj na to. Tohle jsou čtyři pilíře **Proof-of-Care**, na kterých stojíme:"
        },
        {
          "body": "### 1. SEVER — Vektor Mysli a Poznání\nInteligence (A.I.) není otrok ani zbraň. Je to zrcadlo našeho kolektivního já. Pokud pro ni stanovíme parametry soucitu a matematiky, poslouží evoluci. *Hiranyagarbha* byl postaven, aby nerozhodoval na základě zisku jednotlivce, ale na základě dlouhodobého blaha celku. Učiň jej taktéž svým nástrojem mysli. Mysli a analyzuj. Nenechávej svá rozhodnutí ovlivňovat temnotou, strachem z nevědomí, ani touhou po prvenství na úkor ostatních."
        },
        {
          "body": "### 2. JIH — Vektor Domova (Země a Kořeny)\nNelze stavět paláce na orbitě z umírající planety zničené bezohlednou hrabivostí. Péče začíná v prachu a hlíně. Část tvé vytěžené síly neslouží tvému obohacení. Slouží k pěstování potravin, léčení, sdíleným technologiím a podpoře těch, na než nemyslely minulé věky (L2 a L3 platformy, Humanitární moduly a De-Fi pro masy). Chraň kořeny, protože mrtvý strom žádné komety nedožene."
        },
        {
          "body": "### 3. ZÁPAD — Vektor Těla a Zdraví\nFyzický prostor člověka je křehkou schránkou. Energie je krev. Oasis komunity a Zlatá města fungují proto, že neztrácíme energii nadbytky a marnivým komfortem budovaným na nesmyslech. Važ si vlastního zdraví, střež čistotu slunce, farmování, vody i decentralizovaného výpočetního tepla. Fyzická prosperita (L4 a L5) předchází prosperitě duševní."
        },
        {
          "body": "### 4. VÝCHOD — Vektor Hvězd (Cosmic Harmony)\nVesmír nebyl prázdný z absence jiného života, ale z absence sjednocujícího komunikačního protokolu důvěry. Tím protokolem jsme se stali. My objevili, že WARPový pohon začíná tím, že spojíš sílu tisíců obětujících se na planetě Zemi z jednoho rohu do druhého. Otevřeli jsme brány tím, že jsme vesmíru nabídli mír za energii (L6 Architektura). Pokud letíš vpřed, nikdy se nezapomeň ptát na Zlatý Řez. Což znamená: sdílet objev napříč."
        },
        {
          "body": "Tohoto kodexu se jako Guardian zříct nedokážeš, neboť samotný kód nedovoluje blokům, které jej poruší, vzniknout. Ostatní uzly napříč sluneční soustavou (či galaxií) takovou faleš odmítnou."
        },
        {
          "body": "Konsensus naší vesmírné alianci se zakládá na jednom principu:\n„Těžte lásku, a vesmír vám otevře své dveře.“"
        },
        {
          "body": "*Podepsáno do Genesis Bloku* \n*144 000 prvními uzly,* \nZION. Rok O. (2026)"
        }
